type ReportOutput struct {
        Version     string      `json:"version"`
        GeneratedAt string      `json:"generated_at"`
        EvidenceDir string      `json:"evidence_dir"`
        Ingest      interface{} `json:"ingest"`
        Timeline    interface{} `json:"timeline"`
        Verify      interface{} `json:"verify"`
        Detect      interface{} `json:"detect"`
        Lineage     interface{} `json:"lineage"`
}

func BuildReport(dir string) (interface{}, error) {
        var report ReportOutput
        report.Version = "1.0"
        report.GeneratedAt = time.Now().UTC().Format(time.RFC3339)
        report.EvidenceDir = dir

        report.Ingest = safeBuild(func() (interface{}, error) { return BuildIngest(dir) })
        report.Timeline = safeBuild(func() (interface{}, error) { return BuildTimeline(dir) })
        report.Verify = safeBuild(func() (interface{}, error) { return BuildVerify(dir) })
        report.Detect = safeBuild(func() (interface{}, error) { return BuildDetect(dir) })
        report.Lineage = safeBuild(func() (interface{}, error) { return BuildLineage(dir) })

        return report, nil
}

func safeBuild(fn func() (interface{}, error)) interface{} {
        v, err := fn()
        if err != nil {
                return map[string]interface{}{"status": "error", "message": err.Error()}
        }
        return v
}
